update master.products p set current_spec_id = sp.id from master.product_specs sp where sp.product_id = p.id and sp.version = 1;
insert into master.bom_headers (spec_id, status, note) select id, 'DRAFT', 'BOM v1 từ BOM_chi_tiet (Excel 3.0)' from master.product_specs where version = 1;

